async function backupAllData(){if(!manageMode||!can('model.manage'))return toast('Bạn không có quyền sao lưu dữ liệu.');const password=prompt('Nhập mật khẩu mã hóa file backup:');if(!password)return;const plain=JSON.stringify({schema:'IST-LOB-BACKUP',version:1,createdAt:new Date().toISOString(),state,currentKey}),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await backupKey(password,salt),cipher=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,new TextEncoder().encode(plain))),payload={format:'IST-LOB-AES-GCM',salt:bytesToB64(salt),iv:bytesToB64(iv),cipher:bytesToB64(cipher),checksum:await sha256Text(plain)};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download=`IST-LOB-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('Đã xuất backup mã hóa AES-GCM')}
async function restoreAllData(file){if(!file)return;if(!manageMode||!can('model.manage'))return toast('Bạn không có quyền khôi phục dữ liệu.');const password=prompt('Nhập mật khẩu đã dùng để mã hóa file backup:');if(!password)return;try{const payload=JSON.parse(await file.text()),key=await backupKey(password,b64ToBytes(payload.salt)),plain=new TextDecoder().decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:b64ToBytes(payload.iv)},key,b64ToBytes(payload.cipher)));if(await sha256Text(plain)!==payload.checksum)throw new Error('Checksum không hợp lệ');const data=JSON.parse(plain);if(data.schema!=='IST-LOB-BACKUP'||!data.state?.models)throw new Error('Sai định dạng backup');state=data.state;currentKey=state.models[data.currentKey]?data.currentKey:Object.keys(state.models)[0];persistLocal();renderAll();toast('Khôi phục dữ liệu thành công')}catch(error){toast('Không thể khôi phục: sai mật khẩu hoặc file không hợp lệ')}}
