  const records=read('Processes').filter(r=>String(r.process_name).trim());if(!records.length)throw new Error('Processes chưa có công đoạn.');
  draft.processes=records.sort((a,b)=>Number(a.station_no)-Number(b.station_no)).map((r,i)=>{const no=number(r.station_no,'STT');if(!Number.isInteger(no)||no<1||numbers.has(no))throw new Error('STT công đoạn phải là số nguyên dương, không trùng.');numbers.add(no);const id=String(r.station_id||'process-'+crypto.randomUUID());if(ids.has(id))throw new Error('station_id bị trùng.');ids.add(id);const old=base.processes.find(s=>s.id===id),s=old?structuredClone(old):p(id,String(r.process_name),0);s.id=id;s.stt=i+1;s.importNumber=no;s.name=String(r.process_name).trim();s.time=number(r.tt_avg,'T/T (Avg.)');s.taktTime=s.time;s.mp=number(r.mp,'MP');s.auto=yes(r.auto);if(s.auto){s.manualMp=s.mp||s.manualMp||1;s.mp=0}s.multiSkills=String(r.multi_skill).trim()==='*'?[40]:String(r.multi_skill).split(/[;,]/).filter(v=>v.trim()).map(v=>number(v.replace('%',''),'ĐKN'));if(s.multiSkills.some(v=>v<1||v>100))throw new Error('ĐKN phải từ 1 đến 100.');s.skill25=s.multiSkills.includes(25);s.skill40=s.multiSkills.includes(40);s.critical=yes(r.critical);s.side=r.side||s.side||'BOTTOM';s.slotIndex=r.slot_index?number(r.slot_index,'Slot'):i+1;s.isActive=!['NO','FALSE','0'].includes(String(r.active).toUpperCase());s.category=String(r.category||'');s.tags=String(r.tags||'').split(';').filter(Boolean);s.x=number(r.x,'X');s.y=number(r.y,'Y');s.jigs=[];return s});
  for(const r of read('Equipment')){if(!String(r.equipment_name).trim()&&!String(r.equipment_type).trim()&&!String(r.setup_minutes).trim())continue;const s=r.station_id?draft.processes.find(s=>s.id===String(r.station_id)):draft.processes.find(s=>s.importNumber===Number(r.station_no));if(!s)throw new Error('Thiết bị không khớp công đoạn: '+(r.station_id||r.station_no));const eq=String(r.equipment_type||'TEST').trim();s.jigs.push({id:String(r.equipment_id||'j-'+crypto.randomUUID()),eqType:eq,type:eq==='V3'?'press':eq==='ATTACH'?'attach':'tool',name:String(r.equipment_name||'').trim(),setup:number(r.setup_minutes,'Setup')})}
  draft.processes.forEach(s=>delete s.importNumber);draft.manualProcessOrder=true;draft.line=meta.line;draft.type=meta.type;draft.note=String(meta.note||'');draft.equipmentTypes=[...new Set(draft.processes.flatMap(s=>s.jigs.map(j=>j.eqType)))];return draft
