  const rows=m.processes.flatMap((s,i)=>(getJigs(s).length?getJigs(s):[{}]).map(j=>({'STT':i+1,'Công đoạn':s.name,'T/T (Avg.)':stationTime(s),'MP':s.mp,'Máy Auto':s.auto?'YES':'NO','Tỷ lệ Necktime':m.neck?stationCycle(s)/m.neck:0,'ĐKN':stationSkills(s).length?'*':'','Loại thiết bị':j.eqType||'','Tên thiết bị':j.name||'','Setup (phút)':j.setup??'','Trạng thái / Ghi chú':s.statusNote||label(s)})));
