function wireTabExcel(kind){const cap=kind[0].toUpperCase()+kind.slice(1),template=$(kind+'XlsxTemplateBtn'),importButton=$(kind+'XlsxImportBtn'),file=$(kind+'XlsxFile'),save=$(kind+'SaveBtn');template.onclick=()=>{try{downloadTabWorkbook(kind)}catch(error){toast(error.message)}};importButton.onclick=()=>file.click();file.onchange=async()=>{const selected=file.files[0];file.value='';if(!selected)return;try{await importTabWorkbook(selected,kind)}catch(error){toast(error.message)}};save.onclick=async()=>{try{await saveCurrent(activeView==='processes'?'LOB':activeView==='jigs'?'EQUIPMENT':'LAYOUT');toast(`Đã lưu dữ liệu ${cap} của ${model().name}`)}catch(error){toast(error.message)}}}
