function contextAction(action){const target=contextTarget,s=target?.station,shape=target?.shape;if(action==='edit'){if(s)$('quickStationDialog').dataset.stationId=s.id;return openQuickStation()}if(action==='timer'&&s){closeStationContextMenu();return openStopwatch(s)}if(action==='swap'){snapshot();if(s){s.side=s.side==='TOP'?'BOTTOM':'TOP';s.y=s.side==='TOP'?80:320}else if(shape)shape.y=shape.y<390?520:220;recordAudit('Đổi chiều / vị trí',s?.name||shape?.text);closeStationContextMenu();renderAll();persistLocal();scheduleSave()}if(action==='delete'){snapshot();if(s){s.isActive=false}else if(shape){const i=shapeArray().findIndex(o=>o.id===shape.id);if(i>=0)shapeArray().splice(i,1)}recordAudit('Xóa / tắt trạm',s?.name||shape?.text);closeStationContextMenu();renderAll();persistLocal();scheduleSave()}}

